function formatNumber(number) {
	if (number > 9)
		return number;
	return "0" + number;
}
function getGlideDurationInText(duration){
	var milliseconds = new GlideDateTime(duration.getValue()).getNumericValue();
	var totalSeconds = milliseconds / 1000;
	totalSeconds = Math.abs(totalSeconds);
	var days = formatNumber(Math.floor(totalSeconds / 60 / 60 / 24));
	var hours = formatNumber(Math.floor(totalSeconds / 60 / 60) % 24);
	var minutes= formatNumber(Math.floor(totalSeconds / 60) % 60);
	var seconds = formatNumber(totalSeconds % 60);
	if (days == "00")
		return hours + ":" + minutes + ":" + seconds;
	else
		return days + ":" + hours + ":" + minutes + ":" + seconds;
}

var startGDT = new GlideDateTime(jelly.jvar_start);
var identifyGDT = new GlideDateTime(jelly.jvar_identify);
var responseGDT = new GlideDateTime(jelly.jvar_response);
var resolutionGDT = new GlideDateTime(jelly.jvar_resolution);
var closeGDT;
if(jelly.jvar_close)
	closeGDT = new GlideDateTime(jelly.jvar_close);
var identifyDuration = GlideDateTime.subtract(startGDT, identifyGDT);
var responseDuration = GlideDateTime.subtract(identifyGDT, responseGDT);
var resolutionDuration = GlideDateTime.subtract(responseGDT, resolutionGDT);
var closeDuration;
if(jelly.jvar_close)
	 closeDuration = GlideDateTime.subtract(resolutionGDT, closeGDT);

var identifyDurationInText = getGlideDurationInText(identifyDuration);
var responseDurationInText = getGlideDurationInText(responseDuration);
var resolutionDurationInText = getGlideDurationInText(resolutionDuration);
var closeDurationInText;
if(jelly.jvar_close)
	 closeDurationInText = getGlideDurationInText(closeDuration);

var identifyTime = new GlideDateTime(identifyDuration.getValue()).getNumericValue();
var responseTime = new GlideDateTime(responseDuration.getValue()).getNumericValue();
var resolutionTime = new GlideDateTime(resolutionDuration.getValue()).getNumericValue();
var closeTime;
var total;
if(jelly.jvar_close){
	closeTime = new GlideDateTime(closeDuration.getValue()).getNumericValue();
	total = identifyTime + responseTime + resolutionTime + closeTime;
} else
	total = identifyTime + responseTime + resolutionTime;

var identifyPercentage = Math.floor(((identifyTime * 100)/total)*100)/100;
var responsePercentage = Math.floor(((responseTime * 100)/total)*100)/100;
var resolutionPercentage = Math.floor(((resolutionTime * 100)/total)*100)/100;
var closePercentage;
if(jelly.jvar_close)
	closePercentage = Math.floor(((closeTime * 100)/total)*100)/100;
